const setSessionCaptureMode = (vault, enabled) => MEMORY_ADMIN.setSessionCapture(vault, enabled, typeof EMBEDDED_TEMPLATES['config.md'] === 'string' ? EMBEDDED_TEMPLATES['config.md'] : '');
